  static create(kind) {
    if (kind === 'money') return new MoneyFormatter();
    throw new Error('unknown');
  }
}
class MoneyFormatter {
  format(n) { return n.toFixed(2); }
}
function formatMoney(n) { return FormatterFactory.create('money').format(n); }
function formatMoneyLegacy(n) { return (Math.round(n * 100) / 100).toFixed(2); }
function unusedHelper() { return 42; }
module.exports = { formatMoney, formatMoneyLegacy, unusedHelper, FormatterFactory };

